import httpx
import respx

from langchain_transcriptyt import TranscriptYTLoader, TranscriptYTSearchTool, TranscriptYTTranscriptTool

BASE = "https://transcript-yt.com"
T = {
    "videoId": "abc12345678", "title": "T", "author": "A", "channelId": "C", "durationSeconds": 60,
    "language": "en", "translated": False, "autoGenerated": True, "source": "captions", "text": "hello world",
    "segments": [{"start": 0, "duration": 5, "end": 5, "timestamp": "0:00", "text": "hello"},
                 {"start": 42.5, "duration": 5, "end": 47.5, "timestamp": "0:42", "text": "world"}],
}


@respx.mock
def test_loader_video_and_failures():
    respx.post(f"{BASE}/v1/transcripts").mock(return_value=httpx.Response(200, json={
        "results": [{"url": "abc12345678", "ok": True, "transcript": T},
                    {"url": "bad", "ok": False, "error": {"code": "INVALID_VIDEO", "message": "x"}}]}))
    docs = TranscriptYTLoader(["abc12345678", "bad"], api_key="k").load()
    assert len(docs) == 1 and docs[0].page_content == "hello world"
    assert docs[0].metadata["title"] == "T"


@respx.mock
def test_loader_paragraph_chunks():
    route = respx.post(f"{BASE}/v1/transcripts").mock(return_value=httpx.Response(200, json={
        "results": [{"url": "abc12345678", "ok": True, "transcript": T}]}))
    docs = TranscriptYTLoader("abc12345678", chunk="paragraph", chunk_size=500, api_key="k").load()
    assert [d.page_content for d in docs] == ["hello", "world"]
    assert docs[1].metadata["source"].endswith("&t=42s")
    assert b'"paragraphs":true' in route.calls.last.request.content.replace(b" ", b"")


@respx.mock
def test_tools():
    respx.post(f"{BASE}/v1/transcript").mock(return_value=httpx.Response(200, text="# T", headers={"content-type": "text/markdown"}))
    respx.get(f"{BASE}/v1/search").mock(return_value=httpx.Response(200, json={"videos": [
        {"videoId": "abc12345678", "title": "Vid", "channelTitle": "Chan", "durationSeconds": 125, "published": "1 day ago"}]}))
    from transcriptyt import TranscriptYT
    c = TranscriptYT(api_key="k")
    assert TranscriptYTTranscriptTool(client=c).invoke({"url": "abc12345678"}) == "# T"
    out = TranscriptYTSearchTool(client=c).invoke({"query": "x"})
    assert out == "Vid | Chan | 2:05 | 1 day ago | https://www.youtube.com/watch?v=abc12345678"
